inline void Network::Connect(Actor* target,const std::string& endpoint,const std::string& accessKey,bool authority){if(endpoint.size()>2000||accessKey.size()>1000)throw std::invalid_argument("network endpoint");engineCommand("netConnect",{{"target",bridgeId(target)},{"endpoint",endpoint},{"accessKey",accessKey},{"authority",authority}});}
inline void Network::Disconnect(Actor* target){engineCommand("netDisconnect",{{"target",bridgeId(target)}});}
inline void Network::SendRPC(Actor* target,const std::string& event,const std::string& json,bool multicast){if(event.empty()||event.size()>160||json.size()>16384)throw std::invalid_argument("network event");if(!Json::parse(json).is_object())throw std::invalid_argument("network RPC object");engineCommand("netRPC",{{"target",bridgeId(target)},{"event",event},{"json",json},{"multicast",multicast}});}
inline void Network::SetOwner(Actor* target,const std::string& peer){if(peer.empty()||peer.size()>160)throw std::invalid_argument("network owner");engineCommand("netSetOwner",{{"target",bridgeId(target)},{"peer",peer}});}
inline std::string Network::GetStateText(Actor* target){auto& data=gameplayField(target,"network");if(data.empty())engineCommand("netInfo",{{"target",bridgeId(target)}});return data.dump();}
inline bool Network::HasAuthority(Actor* target){auto& data=gameplayField(target,"networkReplica");if(data.empty())engineCommand("netAuthority",{{"target",bridgeId(target)}});return data.value("authority",true);}
