inline Json& bridgeComponent(Actor* actor,const std::string& name){auto* state=bridgeState(actor);if(!state)throw std::runtime_error("component actor missing");for(auto& c:state->at("components"))if(c.value("type",std::string{})==name||c.value("name",std::string{})==name||c.value("id",std::string{})==name){auto& properties=c["properties"];if(c.value("type",std::string{})=="Transform"){properties["position"]=actor->transform.position;properties["rotation"]=actor->transform.rotation;properties["scale"]=actor->transform.scale;}return properties;}throw std::runtime_error("component missing: "+name);}
inline Json& bridgeJointComponent(Actor* target,const std::string& name,bool* planar=nullptr){auto* state=bridgeStateFields(target,{"components"});if(state&&state->contains("components"))for(auto& c:state->at("components")){const auto type=c.value("type",std::string{});if((type=="PhysicsConstraint"||type=="PhysicsConstraint2D")&&(c.value("id",std::string{})==name||c.value("name",std::string{})==name||type==name)){if(planar)*planar=type=="PhysicsConstraint2D";return c["properties"];}}throw std::runtime_error("joint component missing");}
inline void Physics::GetClothParticle(Actor* target,int index,Vec3& position,Vec3& velocity,bool& pinned){if(index<0)throw std::runtime_error("particle index range");const auto result=engineQuery("physicsClothParticle",{{"target",bridgeId(target)},{"index",index}});const auto p=result.at("position").get<Vec3>(),v=result.at("velocity").get<Vec3>();const auto fixed=result.at("pinned").get<bool>();position=p;velocity=v;pinned=fixed;}
inline void Physics::GetRopeParticle(Actor* target,int index,Vec2& position,Vec2& velocity,bool& pinned){if(index<0)throw std::runtime_error("particle index range");const auto result=engineQuery("physicsRopeParticle",{{"target",bridgeId(target)},{"index",index}});const auto p=result.at("position").get<Vec2>(),v=result.at("velocity").get<Vec2>();const auto fixed=result.at("pinned").get<bool>();position=p;velocity=v;pinned=fixed;}
inline void Physics::PinRopeParticle(Actor* target,int index,bool pinned){bridgeComponent(target,"Rope2D");if(index<0)throw std::runtime_error("rope particle index");engineCommand("physicsRopePin",{{"target",bridgeId(target)},{"index",index},{"pinned",pinned}});}
inline void Physics::AddRopeImpulse(Actor* target,const Vec2& impulse,int index){bridgeComponent(target,"Rope2D");if(index< -1||!std::isfinite(impulse.x)||!std::isfinite(impulse.y))throw std::runtime_error("rope impulse");engineCommand("physicsRopeImpulse",{{"target",bridgeId(target)},{"impulse",impulse},{"index",index}});}
