inline void Physics::SetVehicleInput(Actor* target,float throttle,float steering,float brake,float handbrake){if(!std::isfinite(throttle)||!std::isfinite(steering)||!std::isfinite(brake)||!std::isfinite(handbrake)||std::abs(throttle)>1||std::abs(steering)>1||brake<0||brake>1||handbrake<0||handbrake>1)throw std::runtime_error("vehicle input range");auto& p=bridgeComponent(target,"RaycastVehicle");engineCommand("physicsVehicleInput",{{"target",bridgeId(target)},{"throttle",throttle},{"steering",steering},{"brake",brake},{"handbrake",handbrake}});p["throttle"]=throttle;p["steering"]=steering;p["brake"]=brake;p["handbrake"]=handbrake;}
inline void Physics::SetVehicleGear(Actor* target,int gear){auto& p=bridgeComponent(target,"RaycastVehicle");const auto ratios=p.value("gearRatios",std::vector<float>{3.6f,2.19f,1.41f,1.f,.83f});if(gear< -1||gear>static_cast<int>(ratios.size()))throw std::runtime_error("vehicle gear range");engineCommand("physicsVehicleGear",{{"target",bridgeId(target)},{"gear",gear}});p["gear"]=gear;}
inline float Physics::GetVehicleRPM(Actor* target){auto& state=gameplayField(target,"vehicle");return state.is_object()?state.value("engineRPM",0.f):0.f;}
