inline const Json& bridgeVehicleWheel(Actor* target,int index){if(index<0||index>255)throw std::invalid_argument("vehicle wheel index");auto& state=gameplayField(target,"vehicle");static const Json empty;if(!state.is_object())return empty;const auto& wheels=state.at("wheels");if(!wheels.is_array()||index>=static_cast<int>(wheels.size()))throw std::invalid_argument("active vehicle wheel missing");return wheels.at(index);}
inline float Physics::GetVehicleWheelRPM(Actor* target,int index){const auto& wheel=bridgeVehicleWheel(target,index);return wheel.is_object()?wheel.value("rpm",0.f):0.f;}
inline float Physics::GetVehicleWheelSlip(Actor* target,int index){const auto& wheel=bridgeVehicleWheel(target,index);return wheel.is_object()?wheel.value("slip",0.f):0.f;}
inline bool Physics::IsVehicleWheelABSActive(Actor* target,int index){const auto& wheel=bridgeVehicleWheel(target,index);return wheel.is_object()?wheel.value("absActive",false):false;}
inline float Physics::GetVehicleSpeed(Actor* target){auto& state=gameplayField(target,"vehicle");return state.is_object()?state.value("speed",0.0f):0.0f;}
inline Json& bridgeGenericJoint(Actor* target,const std::string& component){bool planar=false;auto& p=bridgeJointComponent(target,component,&planar);if(planar)throw std::runtime_error("generic joint requires3D");if(!p.contains("jointDOFs")||!p["jointDOFs"].is_array()||p["jointDOFs"].size()!=6){p["jointDOFs"]=Json::array();for(int axis=0;axis<6;axis++)p["jointDOFs"].push_back({{"mode","locked"},{"lower",-1},{"upper",1},{"motor",false},{"position",0},{"velocity",0},{"stiffness",100},{"damping",10},{"maxForce",0}});}p["jointType"]="generic";p["useFrames"]=true;p["useMotor"]=false;p["enableLimit"]=false;return p;}
inline void Physics::SetJointAxis(Actor* target,const std::string& component,int axis,const std::string& mode,float lower,float upper){if(axis<0||axis>=6||(mode!="locked"&&mode!="limited"&&mode!="free")||!std::isfinite(lower)||!std::isfinite(upper)||lower>upper||std::abs(lower)>1000000||std::abs(upper)>1000000||(axis>=3&&(lower< -180||upper>180)))throw std::runtime_error("joint axis range");auto& p=bridgeGenericJoint(target,component);engineCommand("physicsJointAxis",{{"target",bridgeId(target)},{"component",component},{"axis",axis},{"mode",mode},{"lower",lower},{"upper",upper}});auto& row=p["jointDOFs"][axis];row["mode"]=mode;row["lower"]=lower;row["upper"]=upper;if(mode=="locked")row["motor"]=false;}
inline void Physics::SetJointAxisMotor(Actor* target,const std::string& component,int axis,bool enabled,float position,float velocity,float stiffness,float damping,float maxForce){for(const float v:{position,velocity,stiffness,damping,maxForce})if(!std::isfinite(v)||std::abs(v)>1000000)throw std::runtime_error("joint axis motor range");if(axis<0||axis>=6||stiffness<0||damping<0||maxForce<0||(axis>=3&&std::abs(position)>180))throw std::runtime_error("joint axis motor range");auto& p=bridgeGenericJoint(target,component);engineCommand("physicsJointAxisMotor",{{"target",bridgeId(target)},{"component",component},{"axis",axis},{"enabled",enabled},{"position",position},{"velocity",velocity},{"stiffness",stiffness},{"damping",damping},{"maxForce",maxForce}});auto& row=p["jointDOFs"][axis];row["motor"]=enabled;row["position"]=position;row["velocity"]=velocity;row["stiffness"]=stiffness;row["damping"]=damping;row["maxForce"]=maxForce;if(enabled&&row.value("mode",std::string{})=="locked")row["mode"]="free";}
inline void Physics::SetJointFrames(Actor* target,const std::string& component,const Vec3& ownerRotation,const Vec3& connectedRotation,bool autoConnected,float referenceAngle){for(const float v:{ownerRotation.x,ownerRotation.y,ownerRotation.z,connectedRotation.x,connectedRotation.y,connectedRotation.z,referenceAngle})if(!std::isfinite(v)||std::abs(v)>360000)throw std::runtime_error("joint frame angle range");bool planar=false;auto& p=bridgeJointComponent(target,component,&planar);if(planar&&(ownerRotation.x!=0||ownerRotation.y!=0||connectedRotation.x!=0||connectedRotation.y!=0))throw std::runtime_error("2D joint frames rotate around Z only");if(planar&&!autoConnected&&p.value("jointType",std::string{})=="slider"){const auto axis=p.value("connectedAxis",Vec3{1,0,0});if(std::hypot(axis.x,axis.y)<=1e-6)throw std::runtime_error("2D slider connected axis missing");}if(!planar){const auto axis=p.value("axis",Vec3{1,0,0}),connected=p.value("connectedAxis",Vec3{1,0,0});if(std::hypot(axis.x,axis.y,axis.z)<=1e-6||(!autoConnected&&std::hypot(connected.x,connected.y,connected.z)<=1e-6))throw std::runtime_error("joint frame axis missing");}engineCommand("physicsJointFrames",{{"target",bridgeId(target)},{"component",component},{"ownerRotation",ownerRotation},{"connectedRotation",connectedRotation},{"autoConnected",autoConnected},{"referenceAngle",referenceAngle}});p["useFrames"]=true;p["frameRotation"]=ownerRotation;p["connectedFrameRotation"]=connectedRotation;p["autoConnectedFrame"]=autoConnected;p["referenceAngle"]=referenceAngle;}
inline void Physics::SetJointBroken(Actor* target,const std::string& component,bool broken){bridgeJointComponent(target,component);engineCommand("physicsJointBreak",{{"target",bridgeId(target)},{"component",component},{"broken",broken}});}
inline void Physics::SetJointMotor(Actor* target,const std::string& component,bool enabled,float position,float velocity,float stiffness,float damping,float maxForce){for(const float v:{position,velocity,stiffness,damping,maxForce})if(!std::isfinite(v))throw std::runtime_error("joint motor finite values");if(std::abs(position)>10000||std::abs(velocity)>10000||stiffness<0||stiffness>1000000||damping<0||damping>1000000||maxForce<0||maxForce>1000000)throw std::runtime_error("joint motor range");auto& p=bridgeJointComponent(target,component);engineCommand("physicsJointMotor",{{"target",bridgeId(target)},{"component",component},{"enabled",enabled},{"position",position},{"velocity",velocity},{"stiffness",stiffness},{"damping",damping},{"maxForce",maxForce}});p["useMotor"]=enabled;p["motorPosition"]=position;p["motorVelocity"]=velocity;p["motorStiffness"]=stiffness;p["motorDamping"]=damping;p["motorMaxForce"]=maxForce;}
inline void Physics::SetJointLimits(Actor* target,const std::string& component,bool enabled,float lower,float upper){if(!std::isfinite(lower)||!std::isfinite(upper)||std::abs(lower)>10000||std::abs(upper)>10000||lower>upper)throw std::runtime_error("joint limit range");auto& p=bridgeJointComponent(target,component);engineCommand("physicsJointLimits",{{"target",bridgeId(target)},{"component",component},{"enabled",enabled},{"lower",lower},{"upper",upper}});p["enableLimit"]=enabled;p["lowerLimit"]=lower;p["upperLimit"]=upper;}
