inline void Components::SetText(Actor* t,const std::string& c,const std::string& p,const std::string& text){auto& properties=bridgeComponent(t,c);std::string componentType;for(const auto& component:bridgeState(t)->at("components"))if(component.value("type",std::string{})==c||component.value("name",std::string{})==c||component.value("id",std::string{})==c){componentType=component.value("type",std::string{});break;}const auto particles=componentSparseParticleCount(componentType,p,properties);if(text.size()>componentJsonTextLimit(particles))throw std::runtime_error("component JSON payload limit");const auto value=Json::parse(text);if(particles)validateSparseComponentJson(value,p,particles);if(!properties.contains(p)&&!particles)throw std::runtime_error("component property missing");for(const auto& component:bridgeState(t)->at("components"))if((component.value("type",std::string{})==c||component.value("name",std::string{})==c||component.value("id",std::string{})==c)&&component.value("type",std::string{})=="Transform"){if(p=="position")t->transform.position=value.get<Vec3>();else if(p=="rotation")t->transform.rotation=value.get<Vec3>();else if(p=="scale")t->transform.scale=value.get<Vec3>();}engineCommand("componentSetJson",{{"target",bridgeId(t)},{"component",c},{"property",p},{"json",text}});properties[p]=value;}
