inline void ReflectionProbes::SetSphere(Actor* t,float v,const std::string& c){if(!std::isfinite(v)||v<.001f||v>1000000.f)throw std::runtime_error("Probe sphere radius outside supported range");engineCommand("reflectionProbeSphere",{{"target",bridgeId(t)},{"component",c},{"value",v}});auto& p=bridgeComponent(t,c);p["volumeShape"]="sphere";p["volumeRadius"]=v;}
inline void ReflectionProbes::SetShape(Actor* t,const std::string& v,const std::string& c){if(v!="box"&&v!="sphere")throw std::runtime_error("Probe shape must be box or sphere");engineCommand("reflectionProbeShape",{{"target",bridgeId(t)},{"component",c},{"value",v}});bridgeComponent(t,c)["volumeShape"]=v;}
inline void ReflectionProbes::SetRadius(Actor* t,float v,const std::string& c){if(!std::isfinite(v)||v<.001f||v>1000000.f)throw std::runtime_error("Probe radius outside supported range");engineCommand("reflectionProbeRadius",{{"target",bridgeId(t)},{"component",c},{"value",v}});bridgeComponent(t,c)["volumeRadius"]=v;}
inline void ReflectionProbes::Refresh(Actor* t,const std::string& c){engineCommand("reflectionProbeRefresh",{{"target",bridgeId(t)},{"component",c}});auto& p=bridgeComponent(t,c);p["refreshVersion"]=(p.value("refreshVersion",0)+1)%16777216;}
inline void ReflectionProbes::SetIntensity(Actor* t,float v,const std::string& c){engineCommand("reflectionProbeIntensity",{{"target",bridgeId(t)},{"component",c},{"value",v}});bridgeComponent(t,c)["intensity"]=v;}
inline void ReflectionProbes::SetDiffuseIntensity(Actor* t,float v,const std::string& c){engineCommand("reflectionProbeDiffuse",{{"target",bridgeId(t)},{"component",c},{"value",v}});bridgeComponent(t,c)["diffuseIntensity"]=v;}
